mkdir -p /tmp/scratch && cat > /tmp/scratch/Scratch.java <<'EOF'
import org.apache.commons.cli.*;
import java.util.*;

public class Scratch {
    public static void main(String[] args) throws Exception {
        Options options = new Options()
            .addOption("a", "enable-a", false, "a")
            .addOption("b", "bfile", true, "b")
            .addOption("c", "copt", false, "c")
            .addOption("D", false, "d");

        GnuParser gp = new GnuParser();
        String[] flat = gp.flatten(options, new String[]{"-c","foober","-btoast"}, true);
        System.out.println("flatten: " + Arrays.toString(flat));

        CommandLine cl = gp.parse(options, new String[]{"-c","foober","-btoast"}, true);
        System.out.println("argList: " + cl.getArgList());

        CommandLine cl2 = gp.parse(options, new String[]{"-Dproperty=value"});
        System.out.println("hasOption D: " + cl2.hasOption("D"));
        System.out.println("getOptionValue D: " + cl2.getOptionValue("D"));
        System.out.println("getOptionValues D: " + Arrays.toString(cl2.getOptionValues("D")));
    }
}
EOF
CP="target/lib/junit-3.8.1.jar:target/classes"
javac -cp "$CP" -d /tmp/scratch /tmp/scratch/Scratch.java
java -cp "/tmp/scratch:$CP" Scratch
